# Tool names shown in the props bar ("Arrow", "Ellipse"…) and rail labels come from the rows above.
CODES = ['de', 'es', 'fr', 'ja']

def main():
    root = os.path.join(os.path.dirname(__file__), '..', 'src', 'locales')
    os.makedirs(root, exist_ok=True)
    seen = set()
    for row in T:
        assert len(row) == 5, row
        assert row[0] not in seen, f'duplicate: {row[0]}'
        seen.add(row[0])
        import re
        ph = set(re.findall(r'\{\w+\}', row[0]))
        for i, tr in enumerate(row[1:]):
            assert set(re.findall(r'\{\w+\}', tr)) == ph, (row[0], CODES[i], tr)
    for i, code in enumerate(CODES):
        table = {row[0]: row[i + 1] for row in T if row[i + 1] != row[0]}
        body = json.dumps(table, ensure_ascii=False, indent=1, sort_keys=True)
        with open(os.path.join(root, f'{code}.js'), 'w', encoding='utf-8') as f:
            f.write(f"// {code}: generated from scripts/locales-source.py — edit there, not here.\n"
                    "// Machine-drafted; have a native speaker review before release.\n"
                    f"(function (root) {{\n  const table = {body};\n"
                    "  if (typeof module === 'object' && module.exports) module.exports = table;\n"
                    f"  else if (root.JPi18n) root.JPi18n.add('{code}', table);\n"
                    "})(typeof self !== 'undefined' ? self : this);\n")
        print(code, len(table), 'strings')

if __name__ == '__main__':
    main()
